'use strict';
const beforeLoopSidebar=renderSidebar;
renderSidebar=function(){beforeLoopSidebar();document.getElementById('sidebar').innerHTML=document.getElementById('sidebar').innerHTML.replace('</nav>',navButton('loops','check','Implementation loops')+'</nav>');};
function loopsPage(){const r=implementationLoopReport;return head('Implementation loops','Small increments, explicit evidence and a stop when a dependency is missing.',`<a class="button-link" href="Clinical_Admin_Implementation_Loops.md" download>Download loop runbook</a>`)+`${r.result==='failed'?`<div class="notice amber" role="alert"><strong>Verification failed.</strong> ${r.sourceChanged?'Source files changed during the run. Run verification again against stable inputs. ':''}${r.unassignedTests?.length?'Node suites missing from the loop ledger: '+r.unassignedTests.map(esc).join(', ')+'. ':''}${r.syntaxChecks?.some(c=>c.result==='failed')?'One or more source files failed syntax checks. ':''}Inspect the recorded results before using this evidence.</div>`:''}<div class="plan-summary"><div><span class="eyebrow">RECORDED BUILD EVIDENCE</span><h2>${r.loops.filter(l=>l.result==='passed').length} local loops passed · ${r.loops.filter(l=>l.result==='blocked').length} await dependencies</h2><p>${r.totalPassed} local automated tests passed. ${r.sourceManifest?.length||0} source files fingerprinted; browser execution results are recorded separately in CI. This snapshot does not run tests in your browser or approve a clinical release.</p><p class="fine">${esc(r.verification)} · Recorded ${esc(r.generatedAt.slice(0,16).replace('T',' '))} UTC</p></div><button onclick="download('clinical-admin-loop-evidence.json',JSON.stringify(implementationLoopReport,null,2),'application/json')">Export evidence snapshot</button></div><div class="extension-grid">${r.loops.map(l=>`<article class="panel extension-card"><div class="panel-head"><span class="pill grey">${l.id}</span><span class="pill ${l.result==='passed'?'green':'amber'}">${l.result==='passed'?'Local checks passed':l.result==='blocked'?'Dependency blocked':esc(l.result)}</span></div><h2>${esc(l.title)}</h2><p>${esc(l.acceptance)}</p><p class="fine">Work packages: ${l.packages.join(' · ')}</p>${l.mode==='local'?`<div class="notice">${l.testsPassed} tests passed. ${esc(l.limit)}</div>`:`<ul class="loop-blockers">${l.blockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><p class="fine">Next: ${esc(l.next)}</p>`}<button class="wide" onclick="loopDetail('${l.id}')">Inspect evidence & next step →</button></article>`).join('')}</div><div class="notice">Loops are finite engineering cycles: inspect → implement → test → record. No background job or automatic production deployment has been scheduled. All patient workflows here use fictional records.</div>`;}
function loopDetail(id){const l=implementationLoopReport.loops.find(l=>l.id===id);modal(l.id+' · '+l.title,`<p>${esc(l.acceptance)}</p>${l.tests?`<h3>Local evidence</h3><ul>${l.tests.map(t=>`<li><code>${t}</code></li>`).join('')}</ul><p>${esc(l.limit)}</p>`:`<h3>Required inputs</h3><ul>${l.blockers.map(b=>`<li>${esc(b)}</li>`).join('')}</ul><p>${esc(l.next)}</p>`}<h3>Linked work packages</h3><div class="chips">${l.packages.map(id=>`<button onclick="workPackage('${id}')">${id}</button>`).join('')}</div><p class="fine">A local test result does not change the original production work-package approval status.</p>`);}
const beforeLoopRender=render;
render=function(){beforeLoopRender();if(route==='loops'){document.getElementById('main').innerHTML=loopsPage();const bc=document.querySelector?.('.breadcrumb b');if(bc)bc.textContent='Implementation loops';}};
const beforeLoopDelivery=deliveryPage;
deliveryPage=function(){return `<div class="journey">${icon('check')}<div><h3>Implementation loops are underway</h3><p>Inspect the recorded tests, applied changes and remaining dependencies.</p></div><button onclick="nav('loops')">Open loop ledger →</button></div>`+beforeLoopDelivery();};
if(location.hash==='#loops')route='loops';
render();
